"""Local web app server generated by Atlas.

Standard library only: http.server for HTTP and sqlite3 for storage. The
data model lives in schema.json and its database changes in migrations.py;
the HTML interface in static/ reads the model from /api/_schema.

The server listens on 127.0.0.1 only. Atlas passes PORT and ATLAS_APP_DATA
(the data folder) in the environment.
"""

import datetime
import json
import os
import re
import sqlite3
import sys
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, unquote, urlparse

from migrations import MIGRATIONS

ROOT = Path(__file__).resolve().parent
SCHEMA = json.loads((ROOT / "schema.json").read_text(encoding="utf-8"))
ENTITIES = {e["name"]: e for e in SCHEMA["entities"]}
DATA_DIR = Path(os.environ.get("ATLAS_APP_DATA") or (ROOT / "data")).resolve()
DB_PATH = DATA_DIR / "app.db"
STATIC = (ROOT / "static").resolve()
MAX_BODY = 1 << 20
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
CONTENT_TYPES = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".ico": "image/x-icon",
    ".json": "application/json",
}


def connect():
    conn = sqlite3.connect(DB_PATH, timeout=15)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def latest_version():
    return max((version for version, _ in MIGRATIONS), default=0)


def migrate():
    """Apply pending migrations, each in its own transaction."""
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    conn = connect()
    conn.isolation_level = None
    try:
        current = conn.execute("PRAGMA user_version").fetchone()[0]
        if current > latest_version():
            raise SystemExit(
                f"The database schema ({current}) is newer than this app ({latest_version()})."
            )
        for version, statements in sorted(MIGRATIONS):
            if version <= current:
                continue
            conn.execute("BEGIN")
            try:
                for statement in statements:
                    conn.execute(statement)
                conn.execute(f"PRAGMA user_version = {int(version)}")
                conn.execute("COMMIT")
            except Exception:
                conn.execute("ROLLBACK")
                raise
    finally:
        conn.close()


class InvalidInput(Exception):
    def __init__(self, field, message):
        super().__init__(message)
        self.field = field
        self.message = message


def coerce(field, value):
    """Validate one value against its field type."""
    kind = field["type"]
    if value is None or value == "":
        if field.get("required"):
            raise InvalidInput(field["name"], "required")
        return None
    if kind in ("text", "longtext"):
        if not isinstance(value, str):
            raise InvalidInput(field["name"], "must be text")
        limit = 200 if kind == "text" else 10000
        if len(value) > limit:
            raise InvalidInput(field["name"], f"must be at most {limit} characters")
        return value.strip()
    if kind == "integer":
        if isinstance(value, bool):
            raise InvalidInput(field["name"], "must be a whole number")
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise InvalidInput(field["name"], "must be a whole number")
        if number != int(number):
            raise InvalidInput(field["name"], "must be a whole number")
        return int(number)
    if kind == "number":
        if isinstance(value, bool):
            raise InvalidInput(field["name"], "must be a number")
        try:
            return float(value)
        except (TypeError, ValueError):
            raise InvalidInput(field["name"], "must be a number")
    if kind == "date":
        if not isinstance(value, str) or not DATE_RE.match(value):
            raise InvalidInput(field["name"], "must be a date (YYYY-MM-DD)")
        try:
            datetime.date.fromisoformat(value)
        except ValueError:
            raise InvalidInput(field["name"], "must be a real date")
        return value
    if kind == "boolean":
        if isinstance(value, bool):
            return 1 if value else 0
        if value in (0, 1, "0", "1", "true", "false"):
            return 1 if value in (1, "1", "true") else 0
        raise InvalidInput(field["name"], "must be true or false")
    if kind == "choice":
        if value not in field.get("choices", []):
            raise InvalidInput(field["name"], "must be one of the listed choices")
        return value
    raise InvalidInput(field["name"], "has an unknown type")


def validate(entity, payload, partial):
    if not isinstance(payload, dict):
        raise InvalidInput("", "the body must be a JSON object")
    values = {}
    for field in entity["fields"]:
        name = field["name"]
        if partial and name not in payload:
            continue
        values[name] = coerce(field, payload.get(name))
    return values


def to_json(entity, row):
    item = dict(row)
    for field in entity["fields"]:
        if field["type"] == "boolean" and item.get(field["name"]) is not None:
            item[field["name"]] = bool(item[field["name"]])
    return item


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")


class Handler(BaseHTTPRequestHandler):
    server_version = "AtlasApp/1"

    def log_message(self, fmt, *args):
        sys.stdout.write("%s %s\n" % (self.log_date_time_string(), fmt % args))

    # Responses ------------------------------------------------------------

    def send_json(self, status, body):
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def send_error_json(self, status, message, field=""):
        self.send_json(status, {"error": message, "field": field})

    def send_empty(self, status):
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.end_headers()

    # Request guards -------------------------------------------------------

    def host_allowed(self):
        """Refuse requests whose Host is not this machine (DNS rebinding)."""
        host = (self.headers.get("Host") or "").rsplit(":", 1)[0].strip("[]").lower()
        return host in ("127.0.0.1", "localhost", "::1")

    def read_json(self):
        if "application/json" not in (self.headers.get("Content-Type") or ""):
            raise InvalidInput("", "send JSON with Content-Type: application/json")
        length = int(self.headers.get("Content-Length") or 0)
        if length > MAX_BODY:
            raise InvalidInput("", "the request is too large")
        raw = self.rfile.read(length) if length else b"{}"
        try:
            return json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise InvalidInput("", "the body is not valid JSON")

    def route(self):
        path = unquote(urlparse(self.path).path)
        parts = [p for p in path.split("/") if p]
        return path, parts

    def dispatch(self, method):
        if not self.host_allowed():
            self.send_error_json(HTTPStatus.FORBIDDEN, "unknown host")
            return
        path, parts = self.route()
        try:
            if parts[:1] == ["api"]:
                self.api(method, parts[1:])
            elif method == "GET" and path == "/healthz":
                self.health()
            elif method == "GET":
                self.static(path)
            else:
                self.send_error_json(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")
        except InvalidInput as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, exc.message, exc.field)
        except sqlite3.Error as exc:
            sys.stderr.write(f"Database error: {exc}\n")
            self.send_error_json(HTTPStatus.INTERNAL_SERVER_ERROR, "database error")

    def do_GET(self):
        self.dispatch("GET")

    def do_POST(self):
        self.dispatch("POST")

    def do_PUT(self):
        self.dispatch("PUT")

    def do_DELETE(self):
        self.dispatch("DELETE")

    # Endpoints --------------------------------------------------------------

    def health(self):
        conn = connect()
        try:
            version = conn.execute("PRAGMA user_version").fetchone()[0]
        finally:
            conn.close()
        self.send_json(HTTPStatus.OK, {"status": "ok", "app": SCHEMA.get("app_id"), "schema_version": version})

    def static(self, path):
        rel = "index.html" if path in ("", "/") else path.lstrip("/")
        target = (STATIC / rel).resolve()
        if STATIC not in target.parents and target != STATIC:
            self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
            return
        if not target.is_file():
            self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
            return
        data = target.read_bytes()
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", CONTENT_TYPES.get(target.suffix, "application/octet-stream"))
        self.send_header("Content-Length", str(len(data)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(data)

    def api(self, method, parts):
        if parts == ["_schema"] and method == "GET":
            self.send_json(HTTPStatus.OK, SCHEMA)
            return
        if parts == ["_summary"] and method == "GET":
            self.summary()
            return
        if not parts or parts[0] not in ENTITIES:
            self.send_error_json(HTTPStatus.NOT_FOUND, "unknown collection")
            return
        entity = ENTITIES[parts[0]]
        if len(parts) == 1:
            if method == "GET":
                self.list(entity)
            elif method == "POST":
                self.create(entity)
            else:
                self.send_error_json(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")
            return
        if len(parts) != 2 or not parts[1].isdigit():
            self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
            return
        record_id = int(parts[1])
        if method == "GET":
            self.read(entity, record_id)
        elif method == "PUT":
            self.update(entity, record_id)
        elif method == "DELETE":
            self.delete(entity, record_id)
        else:
            self.send_error_json(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    def list(self, entity):
        query = parse_qs(urlparse(self.path).query)
        text = (query.get("q") or [""])[0].strip()
        try:
            limit = min(max(int((query.get("limit") or ["500"])[0]), 1), 1000)
        except ValueError:
            limit = 500
        sql = f'SELECT * FROM "{entity["name"]}"'
        args = []
        searchable = [f["name"] for f in entity["fields"] if f["type"] in ("text", "longtext", "choice")]
        if text and searchable:
            sql += " WHERE " + " OR ".join(f'"{name}" LIKE ?' for name in searchable)
            args = [f"%{text}%"] * len(searchable)
        sql += " ORDER BY id DESC LIMIT ?"
        args.append(limit)
        conn = connect()
        try:
            rows = conn.execute(sql, args).fetchall()
        finally:
            conn.close()
        self.send_json(HTTPStatus.OK, {"items": [to_json(entity, r) for r in rows]})

    def read(self, entity, record_id):
        conn = connect()
        try:
            row = conn.execute(f'SELECT * FROM "{entity["name"]}" WHERE id = ?', (record_id,)).fetchone()
        finally:
            conn.close()
        if row is None:
            self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
            return
        self.send_json(HTTPStatus.OK, to_json(entity, row))

    def create(self, entity):
        values = validate(entity, self.read_json(), partial=False)
        stamp = now()
        columns = list(values) + ["created_at", "updated_at"]
        args = list(values.values()) + [stamp, stamp]
        sql = 'INSERT INTO "{}" ({}) VALUES ({})'.format(
            entity["name"], ", ".join(f'"{c}"' for c in columns), ", ".join("?" for _ in columns)
        )
        conn = connect()
        try:
            with conn:
                cursor = conn.execute(sql, args)
            row = conn.execute(f'SELECT * FROM "{entity["name"]}" WHERE id = ?', (cursor.lastrowid,)).fetchone()
        finally:
            conn.close()
        self.send_json(HTTPStatus.CREATED, to_json(entity, row))

    def update(self, entity, record_id):
        values = validate(entity, self.read_json(), partial=True)
        values["updated_at"] = now()
        sql = 'UPDATE "{}" SET {} WHERE id = ?'.format(
            entity["name"], ", ".join(f'"{c}" = ?' for c in values)
        )
        conn = connect()
        try:
            with conn:
                cursor = conn.execute(sql, list(values.values()) + [record_id])
            if cursor.rowcount == 0:
                self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
                return
            row = conn.execute(f'SELECT * FROM "{entity["name"]}" WHERE id = ?', (record_id,)).fetchone()
        finally:
            conn.close()
        self.send_json(HTTPStatus.OK, to_json(entity, row))

    def delete(self, entity, record_id):
        conn = connect()
        try:
            with conn:
                cursor = conn.execute(f'DELETE FROM "{entity["name"]}" WHERE id = ?', (record_id,))
        finally:
            conn.close()
        if cursor.rowcount == 0:
            self.send_error_json(HTTPStatus.NOT_FOUND, "not found")
            return
        self.send_empty(HTTPStatus.NO_CONTENT)

    def summary(self):
        """Counts per collection and totals of numeric fields."""
        out = {}
        conn = connect()
        try:
            for name, entity in ENTITIES.items():
                numeric = [f["name"] for f in entity["fields"] if f["type"] in ("integer", "number")]
                selects = ["COUNT(*) AS count"] + [f'COALESCE(SUM("{n}"), 0) AS "{n}"' for n in numeric]
                row = conn.execute(f'SELECT {", ".join(selects)} FROM "{name}"').fetchone()
                out[name] = {"count": row["count"], "totals": {n: row[n] for n in numeric}}
        finally:
            conn.close()
        self.send_json(HTTPStatus.OK, out)


def main():
    port = int(os.environ.get("PORT") or SCHEMA.get("default_port") or 0)
    migrate()
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.daemon_threads = True
    print(f"Listening on http://127.0.0.1:{server.server_address[1]}/ (data: {DATA_DIR})", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
